CREATE TABLE vehicle_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT UNSIGNED NOT NULL, driver_id BIGINT UNSIGNED NOT NULL, assigned_by_user_id BIGINT UNSIGNED NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NULL, purpose VARCHAR(255) NULL, status ENUM('active','completed','cancelled') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_va_vehicle_status_dates (vehicle_id,status,starts_at,ends_at), KEY idx_va_driver_status_dates (driver_id,status,starts_at,ends_at), CONSTRAINT chk_va_dates CHECK (ends_at IS NULL OR ends_at > starts_at), CONSTRAINT fk_va_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, CONSTRAINT fk_va_driver FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE RESTRICT, CONSTRAINT fk_va_user FOREIGN KEY (assigned_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
